form(){ file=$1; title=$2; a=$3; b=$4; c=$5; d=$6; unit1=$7; unit2=$8; note=$9;
cat > pages/$file <<EOF
<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>$title</title><link rel="stylesheet" href="../styles.css"></head><body><main class="form-page"><section class="hero"><div class="hero-left"><span class="hero-icon">▥</span><div><h2>$title</h2><p>Isi semua field yang diperlukan dengan benar</p></div></div><span class="form-chip">Form Input</span></section><div class="form-body"><div class="form-grid"><div class="field"><label><span class="label-icon">▥</span>$a <span class="required">*</span></label><div class="control"><input placeholder="$c"><span class="unit">$unit1</span></div><div class="hint">Contoh: $d</div></div><div class="field"><label><span class="label-icon">▥</span>$b <span class="required">*</span></label><div class="control"><input placeholder="Masukkan durasi penyemprotan"><span class="unit">$unit2</span></div><div class="hint">Contoh: $note</div></div></div><section class="info-box"><span class="info-icon">i</span><h3>Informasi Penting</h3><p>Pastikan nilai yang dimasukkan sesuai dengan kebutuhan sistem hidroponik Anda. Nilai yang terlalu tinggi atau terlalu rendah dapat mempengaruhi pertumbuhan tanaman secara signifikan.</p><span class="warn">● Periksa kembali sebelum menyimpan</span></section><div class="form-bottom"><div class="required-note"><b>*</b> Wajib diisi</div><div class="form-actions"><button class="btn-secondary">Batal</button><button class="btn-secondary">↻ Ulang</button><button class="btn-save">▣ Simpan Data</button></div></div></div></main></body></html>
EOF
}
